head.script:
scwin.btn1_onclick = function(e) {
    alert(dataMap1.get("key1"));
};
scwin.btn2_onclick = function(e) {
    /// inputCalendar의 값이 변하는 시점(setValue)에서 적용 되도록 ///////////
    //////////// 이 부분을 공통으로 처리 할 수 있는 옵션이나
    //////////// formatter 함수가 필요합니다. //////// 
    var formattedVal = ipt1.getFormattedValue();
    dataMap1.set("key1", formattedVal);
    ///////////////////////////////////////////////
    al = dataMap1.get("key1");
    //alert(dataMap1.get("key1"));
};
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 2. 브라우저에서 formatted 값 버튼을 클릭한다
    //1.2. Click the formatted value button in your browser
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn2').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    // verify step 2. 팝업창에 '2016-05-30' 라고 표시된다.  
    //2. '2016-05-30' is displayed in the popup window.
    WebSquare.wUnit.addCommand("assert", "al", "2016-05-30");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    ipt1.setValue("20160530");
    window.al = "";
    //Function unitTest
    //Created By: Sang.do
    //Created By: 08-Feb-2018
    //end unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
